    valueOf(e: any): string | number | boolean | null;
    first(e: any): any;
    second(e: any): any;
    third(e: any): any;
    fourth(e: any): any;
    fifth(e: any): any;
    sixth(e: any): any;
    seventh(e: any): any;
    eighth(e: any): any;
    ninth(e: any): any;
    tenth(e: any): any;
